"""Spool ticket text. The async wrapper is for the worker process."""

def job_code(job_id):
    if job_id < 0:
        return "job-0000"
    return f"job-{job_id:04d}"

async def spool_ticket(job_id, pages):
    if pages < 1:
        return ""
    return f"{job_code(job_id)} pages={pages}"

"""Practice-room click track. The gap helper is async and unused here."""

async def click_gap_ms(bpm):
    if bpm < 1:
        return 0
    return 60000 // bpm

def beats_in(minutes, bpm):
    if minutes < 0 or bpm < 1:
        return 0
    return minutes * bpm

if __name__ == "__main__":
    beats_in(2, 120)

"""Show length in seconds. track_gap is named only in the menu string."""

menu = "track_gap"

def track_gap(seconds):
    if seconds < 0:
        return 0
    if seconds > 5:
        return 5
    return seconds

def show_length(tracks):
    total = 0
    for seconds in tracks:
        if seconds > 0:
            total += seconds
    return total

if __name__ == "__main__":
    show_length([180, 200, 40])

"""Cell count and soil cups for a seed tray. Neither entry is called here."""

def cells_for(width_mm, cell_mm):
    if width_mm <= 0 or cell_mm <= 0:
        return 0
    return width_mm // cell_mm

def soil_cups(cells):
    if cells < 1:
        return 0
    return (cells + 3) // 4

"""Rest times for a home loaf. Neither timer is called from here."""

def bulk_minutes(temp_f):
    if temp_f >= 80:
        return 180
    if temp_f >= 70:
        return 240
    return 300

def fold_count(hours):
    if hours < 1:
        return 0
    return hours * 2

"""Binding length around a quilt. The bias estimate is not called."""

def bias_extra(inches):
    if inches <= 0:
        return 0
    return inches // 10

def binding_inches(width, height):
    if width < 0 or height < 0:
        return 0
    return 2 * (width + height) + 10

if __name__ == "__main__":
    binding_inches(40, 60)

"""Headspace for a home canning jar. The brine note is not called."""

def brine_note(salt_g):
    if salt_g < 0:
        return "salt 0 g"
    return f"salt {salt_g} g"

def headspace_mm(style):
    if style == "jam":
        return 5
    if style == "pickle":
        return 12
    return 6

if __name__ == "__main__":
    headspace_mm("jam")
